import{_ as n,o as h,c as a,a3 as g}from"./chunks/framework.DX_KL3e0.js";const c="/help/screenshots/duyet-yeu-cau/tong-quan.png",u="/help/screenshots/duyet-yeu-cau/cong.png",i="/help/screenshots/duyet-yeu-cau/xoa-tai-san.png",m=JSON.parse('{"title":"Duyệt yêu cầu","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/duyet-yeu-cau.md","filePath":"chuc-nang/duyet-yeu-cau.md","lastUpdated":1783009205000}'),o={name:"chuc-nang/duyet-yeu-cau.md"};function r(s,t,e,d,l,y){return h(),a("div",null,[...t[0]||(t[0]=[g('<h1 id="duyet-yeu-cau" tabindex="-1">Duyệt yêu cầu <a class="header-anchor" href="#duyet-yeu-cau" aria-label="Permalink to &quot;Duyệt yêu cầu&quot;">​</a></h1><p>Module <strong>Duyệt Yêu Cầu</strong> là trung tâm xét duyệt mọi yêu cầu trong tổ chức. Hiện hỗ trợ <strong>Duyệt Công</strong> (bù công, tăng ca, bảng công, nghỉ phép) và <strong>Duyệt Xóa Tài Sản</strong>; các nhóm khác (công tác, chi phí, mua sắm, lịch làm) sẽ ra mắt sau.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/duyet-yeu-cau</code> (menu <strong>Duyệt Yêu Cầu</strong>).</li><li><strong>Ai dùng được:</strong> Quản Lý — Super Admin, Admin, Manager. Người dùng thường sẽ thấy thông báo &quot;Trang này chỉ dành cho Quản Lý&quot;.</li><li><strong>Nhóm đang hoạt động:</strong> Duyệt Công · Duyệt Xóa Tài Sản (chỉ Super Admin).</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+c+'" alt="Trang Duyệt yêu cầu"></p><p>Đầu trang hiển thị <strong>tổng số yêu cầu đang chờ duyệt</strong>. Mỗi nhóm là một thẻ kèm huy hiệu số lượng chờ. Các nhóm &quot;Sắp ra mắt&quot; hiển thị mờ và chưa bấm được.</p><table tabindex="0"><thead><tr><th>Nhóm</th><th>Đường dẫn</th><th>Ai duyệt</th></tr></thead><tbody><tr><td><strong>Duyệt Công</strong></td><td><code>/duyet-yeu-cau/cong</code></td><td>Super Admin, Admin, Manager</td></tr><tr><td><strong>Duyệt Xóa Tài Sản</strong></td><td><code>/duyet-yeu-cau/xoa-tai-san</code></td><td>Chỉ Super Admin</td></tr><tr><td>Duyệt Công Tác · Chi Phí · Mua Sắm · Lịch Làm</td><td>—</td><td><em>Sắp ra mắt</em></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Phạm vi duyệt theo vai trò</p><ul><li><strong>Manager</strong> chỉ thấy và duyệt yêu cầu của <strong>đội mình</strong>.</li><li><strong>Admin / Super Admin</strong> thấy yêu cầu <strong>toàn tổ chức</strong>.</li><li>Thẻ <strong>Duyệt Xóa Tài Sản</strong> chỉ hiển thị với <strong>Super Admin</strong> (Admin mặc định không có quyền xóa tài sản).</li></ul></div><h2 id="_1-duyet-cong" tabindex="-1">1. Duyệt Công <a class="header-anchor" href="#_1-duyet-cong" aria-label="Permalink to &quot;1. Duyệt Công&quot;">​</a></h2><p>Trang <strong>Duyệt Công</strong> xử lý các yêu cầu liên quan đến thời gian làm việc, chia thành các tab:</p><p><img src="'+u+'" alt="Duyệt công — các tab Bù Công, Tăng Ca, Nghỉ Phép"></p><table tabindex="0"><thead><tr><th>Tab</th><th>Nội dung duyệt</th></tr></thead><tbody><tr><td><strong>Bù Công</strong></td><td>Đề xuất bù công, công tác, WFH, làm theo ca từ nhân viên.</td></tr><tr><td><strong>Tăng Ca</strong></td><td>Khai báo tăng ca (khung tối / khung đêm).</td></tr><tr><td><strong>Nghỉ Phép</strong></td><td>Đơn xin nghỉ phép theo ngày hoặc theo giờ.</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Không còn duyệt bảng công</p><p>Bảng công <strong>không còn nộp/duyệt thủ công</strong> — hệ thống tự chốt &amp; gửi về Bộ Phận Chấm Công khi tới hạn. Quản lý <strong>xem</strong> bảng công đội ngũ tại <a href="/help/chuc-nang/cham-cong.html#_5-bang-cong-xem-bang-cong-doi-ngu-quan-ly">Dữ Liệu Chấm Công → Bảng Công</a> (chỉ xem).</p></div><p><strong>Các bước duyệt:</strong></p><ol><li>Mở <strong>Duyệt Công</strong>, chọn tab phù hợp.</li><li>Xem chi tiết yêu cầu: người gửi, ngày, giờ đề xuất, số ngày công / giờ tăng ca, lý do.</li><li>Nhập <strong>ghi chú / phản hồi</strong> nếu cần.</li><li>Bấm <strong>Duyệt</strong> để chấp thuận, hoặc <strong>Từ chối</strong> / <strong>Yêu Cầu Sửa</strong> để trả lại.</li></ol><p>Sau khi duyệt, dữ liệu công của nhân viên được cập nhật tự động. Yêu cầu đã duyệt vẫn có thể được hủy/đảo trong một số trường hợp (bù công, tăng ca).</p><div class="tip custom-block"><p class="custom-block-title">Liên kết với nhân viên</p><p>Nhân viên tạo các yêu cầu này từ module <a href="/help/chuc-nang/cham-cong.html">Dữ liệu Chấm công</a> (bù công/tăng ca trong bảng công, đơn nghỉ phép). Bảng công tự gửi nên <strong>không có bước duyệt bảng công</strong>; quản lý xem bảng công đội ngũ tại <a href="/help/chuc-nang/cham-cong.html#_5-bang-cong-xem-bang-cong-doi-ngu-quan-ly">Bảng Công</a>.</p></div><h2 id="_2-duyet-xoa-tai-san" tabindex="-1">2. Duyệt Xóa Tài Sản <a class="header-anchor" href="#_2-duyet-xoa-tai-san" aria-label="Permalink to &quot;2. Duyệt Xóa Tài Sản&quot;">​</a></h2><p>Trang <strong>Duyệt Xóa Tài Sản</strong> liệt kê các đề xuất thanh lý / xóa tài sản đang chờ. Người duyệt xem xét rồi <strong>phê duyệt</strong> hoặc <strong>từ chối</strong> việc xóa tài sản khỏi hệ thống.</p><p><img src="'+i+'" alt="Duyệt yêu cầu xóa tài sản chờ phê duyệt"></p><div class="warning custom-block"><p class="custom-block-title">Chỉ Super Admin</p><p>Vì tài sản chỉ bị xóa qua luồng duyệt (không xóa trực tiếp), nhóm này được giới hạn cho <strong>Super Admin</strong>. Đề xuất xóa thường được gửi từ chi tiết tài sản trong <a href="/help/chuc-nang/tai-san.html">Quản lý Tài sản</a>.</p></div><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Tôi là Manager nhưng không thấy hết yêu cầu?</strong> Đúng quy tắc — Manager chỉ thấy yêu cầu của đội mình. Admin/Super Admin mới thấy toàn tổ chức.</p><p><strong>Tôi là Admin nhưng không thấy thẻ Duyệt Xóa Tài Sản?</strong> Nhóm này chỉ dành cho Super Admin. Hãy nhờ Super Admin xử lý đề xuất xóa.</p><p><strong>Sau khi tôi duyệt thì điều gì xảy ra?</strong> Với Duyệt Công, dữ liệu công của nhân viên cập nhật ngay. Với Xóa Tài Sản, tài sản được gỡ khỏi hệ thống sau khi phê duyệt.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/cham-cong.html">Dữ liệu Chấm công</a> · <a href="/help/chuc-nang/tai-san.html">Quản lý Tài sản</a> · <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a></p>',27)])])}const b=n(o,[["render",r]]);export{m as __pageData,b as default};
